using System;

class Convertible
{
    [Obsolete("To int")]
    public static implicit operator int(Convertible c)
    {
        return 0;
    }

    [Obsolete("From int")]
    public static implicit operator Convertible(int i)
    {
        return null;
    }
}

class Test
{
    static void Main(string[] args)
    {
        foreach (int i in new Convertible[1])
        {
            Convertible c = new Convertible();
            c++;
            c -= 2;
        }
    }
}

